def edit(x):
 if isinstance(x,str):
  x=re.sub(r'[A-Za-z]{8,}',lambda m:WORD_SPLITS.get(m.group(),m.group()),x)
  for a,b in replacements.items():x=x.replace(a,b)
  x=re.sub(r'([a-z]{3,})(?=[0-9])',r'\1 ',x)
  for a,b in {'ofzero':'of zero','belowc':'below c','thewall':'the wall','and rms':'and rms','andrms':'and rms','isfixed':'is fixed','isbelow':'is below','islarge':'is large','anideal':'an ideal','gaswork':'gas work','Eachleg':'Each leg','fromg/':'from g/','tokg/':'to kg/','ofheat':'of heat','toJ/':'to J/','usingγ':'using γ','the100':'the 100','The1/4':'The 1/4','sothe':'so the'}.items():x=x.replace(a,b)
  return x
 if isinstance(x,list):return [edit(y) for y in x]
 if isinstance(x,dict):return {a:edit(b) for a,b in x.items()}
 return x
